mapper.select:
select c.id as id, c.content as content, c.reply_content as replyContent, u.nickname as nickname, '管理员' as adminName, c.admin_id, c.create_time as createTime, c.update_time as updateTime from cms_consult c left join acl_user u on c.uid = u.id
and ${ew.sqlSegment}
where c.is_deleted = 0 order by c.create_time desc
